CREATE TABLE IF NOT EXISTS customer_success (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL UNIQUE, lifecycle_stage text NOT NULL DEFAULT 'onboarding', health_score integer NOT NULL DEFAULT 50, activation_percent integer NOT NULL DEFAULT 0, last_activity_at timestamptz, next_review_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());